import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {resolveRecommendation} from '../../lib/recommendation-policy.js';
import {root, readJson, readText} from './helpers.js';

const exists = url => fs.existsSync(path.join(root, 'dist', url.replace(/^\//, '').replace(/\/$/, '/index.html')));

const OVERRIDE_HEADING = 'Alternatives for this platform choice:';
const SECTION_END = /^(When `|### |Aliases: |Sources: |Other scoped alternatives:|Alternatives for shared or undecided)/;

// The guide lines an applicable alternative renders as, in resolver order.
const alternativeLines = alternatives => alternatives.flatMap(a => [
  `- ${a.label}${a.profile_id ? ` \`${a.profile_id}\`` : ''}: ${a.choose_when} Tradeoff: ${a.caveat}`,
  '  Sources: ' + a.sources.map(s => `[${s.title}](${s.url})`).join('; ')
]);

function taskLines(choose, task) {
  const lines = choose.split('\n');
  const start = lines.indexOf(`### ${task.label} (\`${task.id}\`)`);
  assert.ok(start >= 0, `choose.md has a section for ${task.id}`);
  const end = lines.findIndex((line, i) => i > start && line.startsWith('### '));
  return lines.slice(start, end < 0 ? lines.length : end);
}

function overrideLines(lines, override) {
  const condition = Object.entries(override.when).map(([key, value]) => `\`${key}=${value}\``).join(', ');
  const start = lines.findIndex(line => line.startsWith(`When ${condition}, use \`${override.primary}\`:`));
  assert.ok(start >= 0, `choose.md has the override for ${condition}`);
  let end = start + 1;
  while (end < lines.length && !(end > start + 2 && SECTION_END.test(lines[end]))) end++;
  return lines.slice(start, end);
}

const blockAfter = (lines, heading) => {
  const start = lines.indexOf(heading);
  if (start < 0) return null;
  const end = lines.indexOf('', start);
  return lines.slice(start + 1, end < 0 ? lines.length : end);
};

test('scenario 8: dist representations agree with their sources', () => {
  assert.ok(fs.existsSync(path.join(root, 'dist')), 'dist/ is built before this check');
  const policy = readJson('menu/recommendations.json');
  assert.deepEqual(JSON.parse(readText('dist/recommendations.json')), policy);

  const choose = readText('dist/choose.md');
  for (const task of policy.use_cases) {
    const lines = taskLines(choose, task);
    const resolved = resolveRecommendation(policy, {use_case: task.id}).task;
    assert.ok(choose.includes(`\`${resolved.primary}\``), `choose.md names primary ${resolved.primary} for ${task.id}`);
    const defaultHeading = lines.find(line => /^(Other scoped alternatives|Alternatives for shared or undecided mobile scope):$/.test(line));
    assert.deepEqual(defaultHeading ? blockAfter(lines, defaultHeading) : [], alternativeLines(resolved.alternatives),
      `choose.md lists the resolver's alternatives for ${task.id}`);

    for (const override of task.overrides || []) {
      const input = {use_case: task.id, ...override.when};
      const {task: selected} = resolveRecommendation(policy, input);
      const section = overrideLines(lines, override);
      assert.ok(section[0].includes(`\`${selected.primary}\``), `choose.md names primary ${selected.primary} for ${JSON.stringify(input)}`);
      const block = blockAfter(section, OVERRIDE_HEADING);
      if (override.alternative_ids || selected.alternatives.length)
        assert.deepEqual(block, alternativeLines(selected.alternatives),
          `choose.md lists the resolver's alternatives under the override for ${JSON.stringify(input)}`);
      else
        assert.equal(block, null, `choose.md has no alternatives heading for ${JSON.stringify(input)}`);
    }
  }

  for (const name of ['recommendation-policy.js', 'migration-fit.js'])
    assert.ok(fs.readFileSync(path.join(root, 'lib', name)).equals(fs.readFileSync(path.join(root, 'dist/design', name))), `${name} is byte-equal`);

  const profiles = readJson('lib/selection-index.json').profiles;
  const advertised = JSON.parse(readText('dist/rewrite/sources.json')).sources;
  const sourceIds = readJson('menu/rewrite-sources.json').sources.map(s => s.id);
  assert.ok(sourceIds.every(id => advertised.some(s => s.id === id)), 'every rewrite source is advertised in dist/rewrite/sources.json');
  const sources = advertised;
  for (const entry of [...profiles, ...sources])
    for (const key of ['guide_url', 'markdown_url', 'json_url'])
      assert.ok(entry[key] && exists(entry[key]), `${entry.id} ${key} ${entry[key]} exists under dist/`);
});

